"""Generate reference vectors from upstream kimodo/motion_rep/smooth_root.py.

Usage: py -3 gen_smooth_root_upstream.py <upstream-kimodo dir> <out.json>

torch and kimodo.tools are stubbed (only get_smooth_root_pos needs torch); we call
smooth_signal / TrajectorySmoother directly with float64 numpy arrays, and also
reproduce the demo's interpolate_path (scipy interp1d linear + smoothing) for a
few waypoint sets.
"""
import importlib.util
import json
import math
import sys
import types

import numpy as np
from scipy.interpolate import interp1d

upstream, out_path = sys.argv[1], sys.argv[2]

# Stubs so the module imports without torch / the kimodo package.
sys.modules["torch"] = types.ModuleType("torch")
kimodo_pkg = types.ModuleType("kimodo")
kimodo_pkg.__path__ = []
tools = types.ModuleType("kimodo.tools")
tools.ensure_batched = lambda **kw: (lambda f: f)
sys.modules["kimodo"] = kimodo_pkg
sys.modules["kimodo.tools"] = tools

spec = importlib.util.spec_from_file_location("smooth_root", f"{upstream}/kimodo/motion_rep/smooth_root.py")
sr = importlib.util.module_from_spec(spec)
spec.loader.exec_module(sr)

rng = np.random.default_rng(1234)


def path(kind, T):
    t = np.arange(T, dtype=np.float64)
    if kind == "straight":
        return np.stack([0.01 * t, 0.03 * t], axis=1)
    if kind == "zigzag":
        return np.stack([0.4 * ((t // 10) % 2 * 2 - 1) + 0.002 * t, 0.025 * t], axis=1)
    if kind == "random":
        return np.cumsum(rng.normal(0, 0.05, size=(T, 2)), axis=0)
    if kind == "circle":
        a = 2 * math.pi * t / max(T, 1)
        return np.stack([np.sin(a), 1 - np.cos(a)], axis=1)
    raise ValueError(kind)


cases = []
for kind, T in [("straight", 5), ("random", 6), ("zigzag", 7), ("random", 17), ("zigzag", 33),
                ("straight", 64), ("random", 100), ("circle", 150), ("zigzag", 181), ("random", 300)]:
    x = path(kind, T)
    margins = np.full(T, 0.06)
    out = sr.smooth_signal(x.copy(), margins)
    cases.append({"name": f"{kind}-{T}", "x": x.tolist(), "out": out.tolist()})

# Single-level TrajectorySmoother results (isolate the ADMM solver).
levels = []
for N, iters, alpha, pw in [(3, 50, 1.8, 0.0), (8, 500, 1.8, 0.0), (20, 100, 1.0, 0.5)]:
    t = path("random", N)
    x0 = np.full_like(t, 0.1)
    margins = np.full(N, 0.06)
    s = sr.TrajectorySmoother(margins, pos_weight=pw, alpha_overrelax=alpha, admm_iters=iters)
    levels.append({"N": N, "iters": iters, "alpha": alpha, "pos_weight": pw,
                   "targets": t.tolist(), "x0": x0.tolist(), "out": s.smooth(t, x0).tolist(),
                   "rho": float(s.admm_stepsize)})

# Demo dense path: interp1d(linear) over waypoints then smoothing (constraint_ui.py:927-956).
dense = []
for frames, waypoints in [
    (180, {0: (0.0, 0.0), 60: (1.0, 2.0), 120: (-1.0, 3.0), 179: (0.5, 4.0)}),
    (150, {0: (0.0, -0.0132), 75: (0.3, 1.5), 149: (0.0, 3.0)}),
    (90, {0: (0.0, 0.0), 89: (2.0, 1.0)}),
]:
    fi = np.array(list(waypoints.keys()))
    xz = np.array(list(waypoints.values()), dtype=np.float64)
    t = np.arange(fi.min(), fi.max() + 1)
    p = np.stack([interp1d(fi, xz[:, 0], kind="linear")(t), interp1d(fi, xz[:, 1], kind="linear")(t)], axis=1)
    if len(fi) >= 3:
        p = sr.smooth_signal(p, np.full(len(p), 0.06))
    dense.append({"frames": frames, "waypoints": [[int(f), *map(float, v)] for f, v in waypoints.items()],
                  "path": p.tolist()})

with open(out_path, "w") as fh:
    json.dump({
        "source": "NVIDIA Kimodo (Apache-2.0) kimodo/motion_rep/smooth_root.py @ upstream clone, float64 numpy; "
                  "generated by tests/fixtures/gen_smooth_root_upstream.py",
        "margin": 0.06, "smooth_signal": cases, "trajectory_smoother": levels, "dense_path": dense,
    }, fh)
print("wrote", out_path, len(cases), "cases")
